import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './BackgroundMap.css';
import axios from 'axios';

// Fix Leaflet icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// Component to recenter the map
const RecenterMap = ({ position }) => {
  const map = useMap();
  useEffect(() => {
    if (position) {
      map.setView(position, 12); // zoom level 12
    }
  }, [position, map]);
  return null;
};

const BackgroundMap = () => {
  const [position, setPosition] = useState([25.276987, 55.296249]); // Default to Dubai
  const [hasLocation, setHasLocation] = useState(false);
  const [locationName, setLocationName] = useState('Detecting...');

  // Get user location
  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        setPosition([latitude, longitude]);
        setHasLocation(true);
      },
      () => {
        setHasLocation(false); // Geolocation denied
      }
    );
  }, []);

  // Reverse geocoding to get location name
  useEffect(() => {
    if (hasLocation) {
      axios
        .get(
          `https://nominatim.openstreetmap.org/reverse?lat=${position[0]}&lon=${position[1]}&format=json`
        )
        .then((res) => {
          const name =
            res.data?.address?.city ||
            res.data?.address?.town ||
            res.data?.address?.village ||
            'Unknown';
          setLocationName(name);
        })
        .catch(() => setLocationName('Unknown'));
    }
  }, [position, hasLocation]);

  return (
    <div className="map-container-wrapper">
      <MapContainer
        center={position}
        zoom={12}
        scrollWheelZoom={false}
        className="background-map"
      >
        <TileLayer
          url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
          attribution="&copy; OpenStreetMap contributors, © Carto"
          detectRetina={true}
        />

        <Marker position={position}>
          <Popup>You are here</Popup>
        </Marker>

        <RecenterMap position={position} />
      </MapContainer>

      {/* Display city name in overlay */}
      <div className="location-label">
        📍 Location: <strong>{locationName}</strong>
      </div>
    </div>
  );
};

export default BackgroundMap;
